<script>
 import {scriptEditorSession,scriptEditorAvailability} from './script-editor-state.js';
 import {scriptEditorMenuItems} from './script-editor-menus.js';
 import {SCRIPT_LANGUAGE_HELP} from './script-editor-language.js';
 import './script-editor.css';
 let {state: scriptEditorState,profile,windowId,available=true,active=true,execute,registerView,dictionary=()=>null}=$props();
 let root,editor,scroller,error=$state(''),saveName=$state('Untitled.applescript');
 let session=$derived(scriptEditorSession(scriptEditorState,windowId)),capability=$derived(scriptEditorAvailability(profile));
 let inventory=$derived(dictionary?.()),query=$derived(session?.dictionaryQuery.toLowerCase()??'');
 const standardTerms=[{name:'activate',syntax:'tell application "app-id"\n  activate\nend tell',description:'Runs registered app.open: focuses an existing simulated window or creates the app’s first window.'},{name:'new window',syntax:'tell application "app-id"\n  new window\nend tell',description:'Runs registered window.create. Apps without multiple-window support reject.'},{name:'quit',syntax:'quit application "app-id"',description:'Calls guarded Root appQuit; unsaved-document refusal is a real runtime error.'}];
 const fileTerms=[{name:'read',syntax:'read file "file-id"\nreturn result',description:'Reads the actual original live virtual File. result contains its source text.'},{name:'write',syntax:'write "text" to file "file-id"\nwrite "text" to new file "New.txt" in folder "documents"',description:'Writes genuine text/plain content with original revision validation.'},{name:'rename',syntax:'rename file "file-id" to "New.txt"',description:'Renames the original File; profile-specific name and collision rules apply.'},{name:'copy',syntax:'copy file "file-id" to folder "documents" as "Copy.txt"',description:'Copies actual bytes, recursively for virtual folders.'},{name:'trash',syntax:'trash file "file-id"',description:'Moves the File/subtree to virtual deleted state; protected folders reject.'},{name:'atomic',syntax:'atomic\n  write "one" to new file "One.txt" in folder "documents"\n  write "two" to new file "Two.txt" in folder "documents"\nend atomic',description:'One all-or-none virtual Files batch, paired with genuine editor log/results quota.'}];
 let commands=$derived((inventory?.commands??[]).filter(row=>row.name.toLowerCase().includes(query)));
 let terms=$derived((session?.dictionarySuite==='standard'?standardTerms:session?.dictionarySuite==='files'?fileTerms:commands).filter(row=>row.name.toLowerCase().includes(query)));
 let term=$derived(terms.find(row=>row.name===session?.dictionaryCommand)??terms[0]);
 async function send(name,payload={}){const r=await execute?.(name,{windowId},payload);error=r?.status==='rejected'?r.error?.message??'Command unavailable.':'';return r;}
 async function edit(event){const element=event.currentTarget;const r=await send('scriptEditor.edit',{source:element.value,selectionStart:element.selectionStart,selectionEnd:element.selectionEnd});if(r?.status==='rejected'&&element===editor&&session)element.value=session.source;}
 function drop(event){const fileId=event.dataTransfer?.getData('application/x-jesteros-file-id');if(fileId){event.preventDefault();send('scriptEditor.open',{fileId});}}
 function keydown(event){if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='r'){event.preventDefault();send('scriptEditor.run');}else if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='s'){event.preventDefault();send('scriptEditor.save');}else if(event.key==='Escape'&&session?.running){event.preventDefault();send('scriptEditor.stop');}}
 $effect(()=>{const id=windowId;if(!root||typeof registerView!=='function'||!session)return;const originalRoot=root,originalState=scriptEditorState,originalSession=session,originalEditor=editor,originalScroller=scroller,mounted=()=>root===originalRoot&&originalRoot.isConnected&&scriptEditorState===originalState&&scriptEditorSession(scriptEditorState,id)===originalSession&&available===true;const facade={available:mounted,focus(controlId,guard){if(guard?.()!==true||!mounted())return false;const control=Array.from(originalRoot.querySelectorAll('[data-control]')).find(c=>c.dataset.control===controlId);if(!control||control.disabled)return false;control.focus();return guard()===true&&mounted()&&document.activeElement===control;},scroll({top},guard){if(guard?.()!==true||!mounted()||scroller!==originalScroller||!originalScroller)return false;originalScroller.scrollTop=top;return guard()===true&&mounted();},selectError(guard){if(guard?.()!==true||!mounted()||editor!==originalEditor||!originalEditor)return false;originalEditor.focus();originalEditor.setSelectionRange(originalSession.selectionStart,originalSession.selectionEnd);return guard()===true&&mounted();}};return registerView(id,facade);});
</script>
{#if session}
<section bind:this={root} class="script-editor-app" class:classic={/high-sierra|mojave/u.test(profile.id)} class:windows={profile.id.startsWith('windows11')} class:active aria-label={capability.label} ondragover={e=>e.preventDefault()} ondrop={drop}>
 <nav class="script-editor-menus" aria-label="Script Editor menus">{#each scriptEditorMenuItems(scriptEditorState,windowId) as menu}<details><summary>{menu.label}</summary><div class="script-editor-menu-popup">{#each menu.items as item}<button disabled={!item.enabled} onclick={()=>send(item.command,item.payload)}>{item.label}</button>{/each}</div></details>{/each}</nav>
 <header class="script-editor-toolbar"><div><button data-control="stop" title="Stop (Escape)" disabled={!session.running} onclick={()=>send('scriptEditor.stop')}><span>■</span>Stop</button><button data-control="run" title="Run (Command-R / Ctrl-R)" disabled={session.running} onclick={()=>send('scriptEditor.run')}><span>▶</span>Run</button><button data-control="compile" disabled={session.running} onclick={()=>send('scriptEditor.compile')}><span>⚒</span>Compile</button></div><strong>{session.title}{session.dirty?' — Edited':''}</strong><button data-control="properties" disabled={session.running} onclick={()=>send('scriptEditor.panel',{panel:'properties'})}>ⓘ<small>Properties</small></button></header>
 <div class="script-editor-language"><span>Language:</span><strong>Simulated AppleScript</strong><span class="script-editor-compile-state">{session.running?'Running…':session.compiledRevision>=0?'Compiled':'Source'}</span><button disabled={session.running} onclick={()=>send('scriptEditor.panel',{panel:'dictionary'})}>Dictionary…</button></div>
 <div class="script-editor-source" style:--script-font-size={scriptEditorState.preferences.fontSize+'px'}><textarea bind:this={editor} data-control="source" aria-label="Script source" spellcheck="false" wrap={scriptEditorState.preferences.wrap?'soft':'off'} value={session.source} disabled={session.running||!available} oninput={edit} onkeydown={keydown}></textarea></div>
 {#if session.error}<div class="script-editor-compile-error" role="alert"><strong>{session.error.line}:{session.error.column}</strong> {session.error.message}</div>{/if}
 <div class="script-editor-panel-tabs" role="tablist" aria-label="Script output">{#each ['result','log','history'] as tab}<button role="tab" disabled={session.running} aria-selected={session.tab===tab} onclick={()=>send('scriptEditor.tab',{tab})}>{tab==='result'?'Result':tab==='log'?'Events / Replies':'Source History'}</button>{/each}<span></span>{#if session.tab!=='result'}<button disabled={session.running} onclick={()=>send('scriptEditor.clear',{panel:session.tab})}>Clear</button>{/if}</div>
 <div bind:this={scroller} class="script-editor-output" role="tabpanel" aria-label={session.tab}>
 {#if session.tab==='result'}<pre>{session.result||'No result yet.'}</pre>{:else if session.tab==='log'}{#each session.log as row}<article class="script-editor-event"><span>{row.kind} · line {row.line} · scene {row.time}</span><pre>{row.text}</pre></article>{/each}{#if !session.log.length}<p>Run a script to view genuine command outcomes and log expressions.</p>{/if}{:else}{#each session.history.toReversed() as row}<article class="script-editor-event"><div><span>{row.kind} · scene {row.time}</span><button disabled={session.running} onclick={()=>send('scriptEditor.restore',{entryId:row.id})}>Restore Source</button></div><pre>{row.text}</pre></article>{/each}{#if !session.history.length}<p>Compile, run, open or save to retain a bounded source snapshot.</p>{/if}{/if}
 </div>
 <footer class="script-editor-footer"><span>{session.source.length} characters · UTF-8 source</span><span>{session.fileId?'File '+session.fileId+' · revision '+session.fileRevision:'Unsaved source'}</span></footer>
 <div class="script-editor-disclosure">{capability.disclosure}</div>
 {#if error}<div class="script-editor-action-error" role="alert">{error}<button onclick={()=>error=''} aria-label="Dismiss error">×</button></div>{/if}
 {#if session.panel!=='none'}<div class="script-editor-shade"><section class="script-editor-sheet" role="dialog" aria-modal="true" aria-label={'Script Editor '+session.panel}>
 {#if session.panel==='dictionary'}<h2>Library — Simulated Scripting Dictionary</h2><label>Search vocabulary<input data-control="dictionary-search" value={session.dictionaryQuery} oninput={e=>send('scriptEditor.dictionary',{query:e.currentTarget.value})}/></label>
 <div class="script-editor-dictionary-browser"><div class="script-editor-dictionary-columns"><aside>{#each [['standard','Standard Suite'],['files','Virtual Files'],['commands','Registered Commands']] as [suite,label]}<button class:selected={session.dictionarySuite===suite} onclick={()=>send('scriptEditor.dictionary',{suite})}><span>S</span>{label}<b>▸</b></button>{/each}</aside><div>{#each terms as row}<button class:selected={term===row} onclick={()=>send('scriptEditor.dictionary',{command:row.name})}><span>C</span>{row.name}</button>{/each}</div><div><p>Language</p><strong>Simulated AppleScript</strong><p>No host Apple events</p></div></div>
 <div class="script-editor-dictionary-definition"><h3>{session.dictionarySuite==='standard'?'Standard Suite':session.dictionarySuite==='files'?'Virtual Files':'Registered Commands'}</h3>{#if term}<h4>{term.name}</h4>{#if session.dictionarySuite==='commands'}<p>Actual registered Root command. Only window-targeted commands may use <code>perform</code>; app activation/new/quit use the Standard Suite.</p><pre>Target: {JSON.stringify(term.targetSchema,null,2)}
Payload: {JSON.stringify(term.payloadSchema,null,2)}</pre>{:else}<p>{term.description}</p><pre>{term.syntax}</pre>{/if}{:else}<p>No matching vocabulary.</p>{/if}</div></div>
 <div class="script-editor-dictionary"><h3>Actual Registered Applications</h3>{#each inventory?.applications??[] as app}<p><strong>{app.label??app.name??app.id}</strong> <code>{app.id}</code></p>{/each}{#if !inventory}<p>Root inventory unavailable; app-control commands cannot run.</p>{/if}<h3>Live Windows</h3>{#each inventory?.windows??[] as window}<p><code>{window.id}</code> — {window.title??window.appId}</p>{/each}</div>
 {:else if session.panel==='properties'}<h2>Script Properties</h2><dl><dt>Language</dt><dd>Simulated AppleScript subset</dd><dt>Format</dt><dd>UTF-8 source (not compiled .scpt)</dd><dt>Source</dt><dd>{session.fileId??'No saved File'} · revision {session.fileRevision}</dd><dt>Editor revision</dt><dd>{session.revision}</dd><dt>Compiled revision</dt><dd>{session.compiledRevision<0?'Not compiled':session.compiledRevision}</dd></dl><label>Description (local editor metadata, not embedded in source)<textarea value={session.description} maxlength="2048" oninput={e=>send('scriptEditor.properties',{description:e.currentTarget.value})}></textarea></label>
 {:else if session.panel==='preferences'}<h2>Script Editor {(/sonoma|golden-gate/u.test(profile.id))?'Settings':'Preferences'}</h2><label>Formatting — font size<input type="number" min="10" max="24" value={scriptEditorState.preferences.fontSize} onchange={e=>send('scriptEditor.preferences',{values:{...scriptEditorState.preferences,fontSize:Number(e.currentTarget.value)}})}/></label>{#each [['wrap','Wrap source lines'],['logging','Log events and replies']] as [key,label]}<label class="script-editor-check"><input type="checkbox" checked={scriptEditorState.preferences[key]} onchange={e=>send('scriptEditor.preferences',{values:{...scriptEditorState.preferences,[key]:e.currentTarget.checked}})}/>{label}</label>{/each}<label>Maximum source history entries<input type="number" min="1" max="64" value={scriptEditorState.preferences.historyLimit} onchange={e=>send('scriptEditor.preferences',{values:{...scriptEditorState.preferences,historyLimit:Number(e.currentTarget.value)}})}/></label>
 {:else if session.panel==='save'}<h2>Save Script Source</h2><label>Save As<input data-control="save-name" bind:value={saveName} maxlength="240"/></label><p>Plain text .applescript or .txt only. No invented compiled-script or executable-app format.</p><button onclick={()=>send('scriptEditor.save',{name:saveName,saveAs:true})}>Save to Documents</button>
 {:else if session.panel==='help'}<h2>Permitted Simulated Language</h2><pre class="script-editor-help">{SCRIPT_LANGUAGE_HELP}</pre>
 {:else if session.panel==='close'}<h2>Save changes to {session.title}?</h2><p>Unsaved source changes will be lost.</p><div class="script-editor-close-buttons"><button onclick={()=>send('scriptEditor.closeDecision',{decision:'discard'})}>Don’t Save</button><button onclick={()=>send('scriptEditor.closeDecision',{decision:'cancel'})}>Cancel</button><button onclick={()=>send('scriptEditor.closeDecision',{decision:'save'})}>Save</button></div>{/if}
 {#if session.panel!=='close'}<button class="script-editor-done" onclick={()=>send('scriptEditor.panel',{panel:'none'})}>Done</button>{/if}
 </section></div>{/if}
</section>
{/if}
